def merge_sorted_arrays(left_array, right_array):
    left_index, right_index, merged_array = 0, 0, []
    while left_index < len(left_array) and right_index < len(right_array):
        if left_array[left_index] <= right_array[right_index]:
            merged_array.append(left_array[left_index]); left_index += 1
        else:
            merged_array.append(right_array[right_index]); right_index += 1
    merged_array.extend(left_array[left_index:]); merged_array.extend(right_array[right_index:])
    return merged_array
